'use strict';
const managerDefaults=()=>({name:'Alexander Brown',title:'Account Manager',whatsapp:'',email:'',telegram:'',photo:''});
function ensureManager(){if(!demo.manager)demo.manager=managerDefaults()}
ensureManager();
let photoCatalog={};
fetch('station-photos.json',{cache:'no-cache'}).then(r=>r.ok?r.json():{}).then(v=>{photoCatalog=v;if(selected)updateStationPhoto(selected)}).catch(()=>{});
function updateStationPhoto(s){const item=photoCatalog[s.id]||photoCatalog.network;const image=$('.station-photo img');if(!item)return;image.src=item.path;image.alt=item.alt;$('.photo-location').textContent=photoCatalog[s.id]?`${s.city}, ${s.state} · Station photo`:`Network photo · ${item.location}`;$('.photo-credit').textContent=item.credit;$('.photo-credit').href=item.source}
const originalSelectStation=selectStation;
selectStation=function(id,zoom=false){const ok=originalSelectStation(id,zoom);if(ok){updateStationPhoto(selected);if(zoom&&role==='client')actions.station()}return ok};
function stationDetail(){if(!selected)return;const s=selected;const photo=photoCatalog[s.id]||photoCatalog.network;const plan=demo.plan;const allocated=plan?.stationIds.includes(s.id)?plan.capital/plan.stationIds.length:null;openModal(`<div class="station-dialog-eyebrow">REAL STATION · AFDC ${s.id}</div><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.address)}, ${escapeHtml(s.city)}, ${s.state} ${s.zip}</p>${photo?`<figure class="station-dialog-photo"><img src="${escapeHtml(photo.path)}" alt="${escapeHtml(photo.alt)}"><figcaption>${photoCatalog[s.id]?'Photo of this location':`Network reference: ${escapeHtml(photo.location)}`} · <a href="${escapeHtml(photo.source)}" target="_blank" rel="noopener">${escapeHtml(photo.credit)}</a></figcaption></figure>`:''}<div class="station-detail-grid"><div><small>Network</small><strong>Electrify America</strong></div><div><small>DC fast ports</small><strong>${s.ports}</strong></div><div><small>Maximum listed power</small><strong>${s.maxKw?s.maxKw+' kW':'Not listed'}</strong></div><div><small>Source confirmed</small><strong>${s.confirmed}</strong></div></div><div class="station-invest-box"><div><span>${allocated?'Your demo allocation':'Starting demo rate'}</span><strong>${allocated?money(allocated):'1.6%'} <small>${allocated?'at this station':'per completed session'}</small></strong></div><button class="button primary" data-action="invest-selected">${allocated?'Manage investment selection':'Select for investment'} ${icon('arrow')}</button><small>Demo selection only. This directory listing does not establish company ownership or a real investment offer.</small></div><div class="station-dialog-links"><a href="https://www.google.com/maps/search/?api=1&query=${s.lat},${s.lng}" target="_blank" rel="noopener">Google Maps ↗</a><a href="${s.source}" target="_blank" rel="noopener">AFDC source ↗</a><button data-action="factsheet">Download factsheet</button></div>`)}
actions.station=stationDetail;
actions['invest-selected']=()=>{if(!selected)return;chosenStations=[selected.id];chosenTier='single';investmentDraft=demo.plan?.capital||250;stationPickerQuery='';$('#modal').close();setRole('client');tab='tariffs';renderClientTab()};
actions['manager-settings']=()=>{ensureManager();const m=demo.manager;openModal(`<h2>Manager contact settings</h2><p>These details appear in the Client portal. Empty fields remain unconfigured.</p><form id="manager-form"><label for="manager-name">Manager name</label><input id="manager-name" name="managerName" maxlength="80" value="${escapeHtml(m.name)}" required><label for="manager-whatsapp">WhatsApp · international number</label><input id="manager-whatsapp" name="whatsapp" type="tel" placeholder="+1 212 555 0100" value="${escapeHtml(m.whatsapp)}"><label for="manager-email">Work email</label><input id="manager-email" name="email" type="email" placeholder="manager@your-company.com" value="${escapeHtml(m.email)}"><label for="manager-telegram">Telegram username</label><input id="manager-telegram" name="telegram" placeholder="@username" value="${escapeHtml(m.telegram)}"><label for="manager-photo">Manager photo URL (optional, HTTPS)</label><input id="manager-photo" name="photo" type="url" placeholder="https://…" value="${escapeHtml(m.photo)}"><div class="form-error" id="manager-error" role="alert"></div><button class="button primary" type="submit">Save manager details</button></form>`)};
function refreshManager(){ensureManager();const m=demo.manager;const area=$('.manager-box');if(!area)return;area.innerHTML=`<button class="manager-row manager-profile-button" data-action="manager"><div class="manager-avatar">${m.photo?`<img src="${escapeHtml(m.photo)}" alt="${escapeHtml(m.name)}">`:`<img src="assets/manager.png" width="64" height="64" loading="lazy" decoding="async" alt="Illustrative demo account manager" onerror="this.hidden=true;this.parentElement.dataset.fallback='AB'">`}</div><div><small>Your Account Manager</small><strong>${escapeHtml(m.name)}</strong><span>${m.photo?'Account support':'Demo profile · illustration'}</span></div></button><div class="manager-channels"><button class="manager-channel" data-contact="whatsapp"><span class="round-button green">WA</span><span>WhatsApp</span></button><button class="manager-channel" data-contact="telegram"><span class="round-button cyan">${icon('arrow')}</span><span>Telegram</span></button><button class="manager-channel" data-contact="email"><span class="round-button">${icon('mail')}</span><span>Email</span></button></div><button class="support-inbox-link" data-action="chat">${icon('chat')}Open support inbox <span>↗</span></button>`}
actions.manager=()=>{ensureManager();const m=demo.manager;openModal(`<h2>${escapeHtml(m.name)}</h2><p>Your account manager</p><ul class="modal-list"><li><strong>WhatsApp</strong><small>${escapeHtml(m.whatsapp||'Not configured')}</small></li><li><strong>Email</strong><small>${escapeHtml(m.email||'Not configured')}</small></li><li><strong>Telegram</strong><small>${escapeHtml(m.telegram||'Not configured')}</small></li></ul><div class="manager-channels"><button class="button secondary" data-contact="whatsapp">WhatsApp</button><button class="button secondary" data-contact="telegram">Telegram</button><button class="button secondary" data-contact="email">Email</button></div>${role==='admin'?'<button class="button primary" data-action="manager-settings">Edit contact details</button>':'<button class="button primary" data-action="chat">Open support inbox</button>'}`)};
function contactManager(channel){ensureManager();const m=demo.manager;const value=m[channel];if(!value){openModal(`<h2>${channel==='email'?'Email':channel==='whatsapp'?'WhatsApp':'Telegram'} is not configured</h2><p>Add the manager's real contact details in the Staff console to enable this link.</p><button class="button primary" data-action="configure-manager">Configure manager contacts</button><button class="button secondary" data-action="chat">Use demo support inbox</button>`);return}const url=channel==='whatsapp'?`https://wa.me/${value.replace(/\D/g,'')}`:channel==='telegram'?`https://t.me/${value.replace(/^@/,'')}`:`mailto:${value}?subject=${encodeURIComponent('Eco-Charge portfolio inquiry')}`;if(channel==='email')location.href=url;else window.open(url,'_blank','noopener,noreferrer')}
actions['configure-manager']=()=>{$('#modal').close();setRole('admin');actions['manager-settings']()};
function contractContent(){const p=demo.plan;return `<h1>Investment agreement preview</h1><div class="draft-banner">DEMO DRAFT — NOT EXECUTED — NOT FOR SIGNATURE</div><p><strong>Client:</strong> John Doe (fictional demo profile)<br><strong>Document date:</strong> ${new Date().toISOString().slice(0,10)}</p><h2>1. Company and parties</h2><p>Company legal name, registration number, jurisdiction, authorized representative and client identification must be supplied and verified before an executable agreement can be prepared.</p><h2>2. Proposed participation</h2><p>The proposed model concerns participation through company shares. The legal nature, share class, rights, valuation, transfer restrictions and investor eligibility have not been established in this prototype.</p><h2>3. Demo plan selection</h2><table><tr><td>Selected plan</td><td>${p?escapeHtml(p.name):'Not selected'}</td></tr><tr><td>Simulated capital</td><td>${p?money(p.capital):'Not selected'}</td></tr><tr><td>Number of reference stations</td><td>${p?p.stationIds.length:'Not selected'}</td></tr><tr><td>Proposed demo accrual rate</td><td>${p?p.rate.toFixed(1)+'% per completed session':'Not selected'}</td></tr></table><p>The displayed rate is applied to the capital allocated to the station. It is a simulation, not an established entitlement or a guaranteed return.</p><h2>4. Reference stations and source data</h2><p>Public station locations come from AFDC. Listing an Electrify America station does not establish ALT-INFRA ownership, a partnership, company share rights or availability for investment.</p><h2>5. Terms to be established</h2><p>Actual rights to assets, payment source, operating expenses, reserves, distribution rules, taxes, financial disclosures, loss risk, exit conditions, dispute resolution and applicable law require verified documentation and qualified review.</p><h2>6. Document status</h2><p>This preview only demonstrates viewing, downloading and printing a document from the portal. No agreement has been executed, no funds are transferred and no signatures or seals are included.</p><footer>ALT-INFRA NETWORK / ECO-CHARGE · DEMO DOCUMENT</footer>`}
actions['preview-contract']=()=>openModal(`<h2>Agreement document</h2><p>Review or print the demo draft. The company details and final terms have not been provided.</p><div class="contract-summary"><strong>${demo.plan?escapeHtml(demo.plan.name)+' plan':'Plan not selected'}</strong><small>${demo.plan?money(demo.plan.capital)+' · '+demo.plan.stationIds.length+' reference stations':'Choose a tariff to include its demo parameters.'}</small></div><button class="button primary" data-action="print-contract">Preview & print agreement ${icon('file')}</button><button class="button secondary" data-action="contract">Download PDF preview ${icon('download')}</button>`);
actions['print-contract']=()=>{const win=window.open('','_blank');if(!win){toast('Allow a new tab to open the print preview.');return}win.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Eco-Charge - Agreement preview</title><style>body{font:14px/1.6 Arial,sans-serif;color:#14253c;max-width:740px;margin:32px auto;padding:0 24px}h1{font-size:25px}h2{font-size:16px;margin-top:24px}.draft-banner{padding:12px;border:1px solid #ba9237;background:#fffaeb;font-size:12px;font-weight:bold}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #ddd}td:last-child{text-align:right}footer{margin:35px 0;border-top:1px solid #ccc;padding:10px 0;font-size:10px}button{padding:12px 20px;background:#095897;color:white;border:0;border-radius:5px;cursor:pointer}h2,table{break-inside:avoid}h2{break-after:avoid}@page{size:A4;margin:18mm}@media print{body{max-width:none;margin:0;padding:0;font-size:11px}.print-toolbar{display:none}.draft-banner{background:none}h2{margin-top:15px;font-size:13px}h1{font-size:21px}}</style></head><body><div class="print-toolbar"><button onclick="window.print()">Print / Save as PDF</button></div>${contractContent()}</body></html>`);win.document.close();win.opener=null;win.focus()};
const oldAdminWithTariffs=renderAdmin;
renderAdmin=function(){oldAdminWithTariffs();if(adminTab==='overview')$('#admin-view .admin-layout aside').insertAdjacentHTML('afterbegin',`<section class="panel admin-section"><h2>${icon('users')} CLIENT MANAGER</h2><p>${escapeHtml(demo.manager?.name||'Alexander Brown')}</p><p class="muted" style="font-size:12px">WhatsApp, Telegram, email and profile photo.</p><button class="button secondary" data-action="manager-settings">Edit manager contacts</button></section>`)};
document.addEventListener('click',e=>{const button=e.target.closest('[data-contact]');if(button)contactManager(button.dataset.contact)});
document.addEventListener('submit',e=>{if(e.target.id!=='manager-form')return;e.preventDefault();const f=e.target;const name=f.elements.managerName.value.trim(),whatsapp=f.elements.whatsapp.value.trim(),email=f.elements.email.value.trim(),telegram=f.elements.telegram.value.trim().replace(/^@/,''),photo=f.elements.photo.value.trim();let error='';if(name.length<2)error='Enter the manager name.';else if(whatsapp&&!/^\+?[\d\s()-]{7,25}$/.test(whatsapp)||whatsapp&&(whatsapp.replace(/\D/g,'').length<7||whatsapp.replace(/\D/g,'').length>15))error='Use an international phone number with country code.';else if(telegram&&!/^[a-zA-Z][a-zA-Z0-9_]{4,31}$/.test(telegram))error='Enter a valid Telegram username, not a URL.';else if(photo&&!/^https:\/\//i.test(photo))error='The photo URL must start with https://.';if(error){$('#manager-error').textContent=error;return}demo.manager={name,title:'Account Manager',whatsapp,email,telegram,photo};activity('Staff updated manager contact details');persist();refreshManager();$('#modal').close();if(role==='admin')renderAdmin();toast('Manager details saved in this browser.')});
document.querySelector('[data-action="contract"]').insertAdjacentHTML('afterend','<button class="document-print-button" data-action="preview-contract">'+icon('file')+' Preview & print agreement</button>');
const resetBeforeManager=actions['confirm-reset'];actions['confirm-reset']=()=>{resetBeforeManager();ensureManager();refreshManager();persist()};
refreshManager();
function renderSessionWidget(){const card=$('.performance-card');let widget=$('#session-widget');if(!widget){card.querySelector('.card-heading').hidden=true;card.querySelector('.performance-body').hidden=true;widget=document.createElement('div');widget.id='session-widget';card.append(widget)}ensureTariffs();const plan=demo.plan;const allocation=plan?plan.capital/plan.stationIds.length:1000;const rate=plan?.rate||demo.tariffs[0].rate;const payout=allocation*rate/100;const last=demo.sessions.at(-1);widget.innerHTML=`<div class="session-heading"><h2>YOUR CHARGING ENGINE</h2><span class="simulation-badge">DEMO</span></div><div class="engine-location"><i class="status-dot"></i>${selected?escapeHtml(selected.city)+', '+selected.state:'United States'} <span>· ${selected?selected.ports+' DC ports':'Choose a station'}</span></div><div class="engine-flow"><button class="engine-node" data-action="station"><span>${icon('zap')}</span><small>Charging session</small></button><div class="engine-connector"><i></i></div><button class="engine-node" data-action="tariffs"><span>${rate.toFixed(1)}<em>%</em></span><small>Allocation rate</small></button><div class="engine-connector"><i></i></div><button class="engine-node payout-node" data-action="engine-details"><span>${money(payout)}</span><small>Demo accrual</small></button></div><div class="engine-bottom"><span>${last?`Last test: +${money(last.payout)} credited`:'Select a plan to test a charging event'}</span><button data-action="${plan?'simulate-session':'tariffs'}">${plan?'Run demo session':'Choose plan'} ${icon('arrow')}</button></div>`}
actions['engine-details']=()=>{ensureTariffs();const p=demo.plan;const capital=p?p.capital/p.stationIds.length:1000;const rate=p?.rate||demo.tariffs[0].rate;openModal(`<h2>How the demo accrual works</h2><ol class="engine-explanation"><li><strong>A selected station completes a charging session.</strong><span>In this prototype, you create the event manually.</span></li><li><strong>The demo rate applies to that station's capital allocation.</strong><span>${money(capital)} × ${rate.toFixed(1)}% = ${money(capital*rate/100)}</span></li><li><strong>The test credit appears in the client's demo balance.</strong><span>The manager can inspect the event in the session ledger.</span></li></ol><div class="modal-note">Actual company distributions require verified revenue, costs, distributable earnings and contractual rights. This is a simulation of the proposed formula.</div><button class="button primary" data-action="${p?'simulate-session':'tariffs'}">${p?'Run demo session':'Choose a plan'}</button>`)};
const renderPlanBeforeEngine=renderPlanBar;
renderPlanBar=function(){renderPlanBeforeEngine();renderSessionWidget()};
const selectBeforeEngine=selectStation;
selectStation=function(id,zoom=false){const result=selectBeforeEngine(id,zoom);renderSessionWidget();return result};
renderSessionWidget();
const renderTariffsBeforeGuidance=renderTariffs;
renderTariffs=function(){renderTariffsBeforeGuidance();$('.tariff-hero').insertAdjacentHTML('afterend',`<nav class="selection-steps" aria-label="Selection progress"><button data-action="focus-tiers"><span>1</span>Compare plans</button><button data-action="focus-allocation"><span>2</span>Choose your allocation</button><button data-action="focus-stations"><span>3</span>Select stations & review</button></nav>`);$('.tariff-scenarios').insertAdjacentHTML('afterend',`<section class="panel decision-help"><div><h2>Make the choice at your pace.</h2><p>Compare the same capital and session assumptions. Ask your manager about company rights, costs and access to funds before deciding.</p></div><button class="button secondary" data-action="guided-support">Talk through my options ${icon('chat')}</button></section>`)};
actions['focus-tiers']=()=>$('.tariff-grid')?.scrollIntoView({behavior:'smooth',block:'center'});actions['focus-allocation']=()=>{$('.allocation-panel')?.scrollIntoView({behavior:'smooth',block:'center'});$('#investment-amount')?.focus({preventScroll:true})};actions['focus-stations']=()=>$('.station-picker')?.scrollIntoView({behavior:'smooth',block:'center'});
actions['guided-support']=()=>openModal(`<h2>Let's clarify your options.</h2><p>You can compare the model before making a decision. Share what matters to you and your manager can respond.</p><form id="guided-support-form"><label for="guide-goal">What are you trying to understand?</label><select id="guide-goal"><option>How company participation works</option><option>How session accruals are calculated</option><option>How to compare different station counts</option><option>How funds can be accessed</option></select><label for="guide-concern">What is your main concern?</label><select id="guide-concern"><option>Evidence of ownership and company rights</option><option>Whether operating revenue supports payments</option><option>Losses, fees and access to funds</option><option>Understanding the assumptions</option></select><label for="guide-impact">How does this affect your decision?</label><textarea id="guide-impact" maxlength="600" placeholder="I need this clarified before I can evaluate the plan."></textarea><label for="guide-answer">What would help you decide?</label><textarea id="guide-answer" maxlength="600" placeholder="For example: verified company documents or a breakdown of operating costs."></textarea><button class="button primary" type="submit">Send questions to my manager</button></form>`);
document.addEventListener('submit',e=>{if(e.target.id!=='guided-support-form')return;e.preventDefault();const message=`Goal: ${$('#guide-goal').value}\nConcern: ${$('#guide-concern').value}\nDecision impact: ${$('#guide-impact').value.trim()||'Not specified'}\nRequested information: ${$('#guide-answer').value.trim()||'Please explain the selected topic.'}`;demo.tickets.push({id:`TKT-${Date.now().toString(36).toUpperCase()}`,subject:'Plan discussion',message,status:'Open',date:new Date().toISOString(),reply:''});activity('Client sent structured plan questions to the manager');persist();$('#modal').close();toast('Questions saved in the manager inbox.')});
function ensureClient(){if(!demo.client)demo.client={name:'John Doe',email:'john.doe@example.com',status:'Active',note:''};clients[0].name=demo.client.name;clients[0].email=demo.client.email;clients[0].state=demo.client.status}
ensureClient();
function refreshClientProfile(){ensureClient();if(role==='client'){$('#profile-name').textContent=demo.client.name;$('.profile .avatar').textContent=demo.client.name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()}}
const roleBeforeProfile=setRole;
setRole=function(next){roleBeforeProfile(next);refreshClientProfile()};
actions['edit-client']=()=>{ensureClient();const c=demo.client;openModal(`<h2>Manage client workspace</h2><p>CL-1001 · Changes are reflected in the Client portal.</p><form id="client-edit-form"><label for="client-name">Client name</label><input id="client-name" value="${escapeHtml(c.name)}" maxlength="80" required><label for="client-email">Email</label><input id="client-email" type="email" value="${escapeHtml(c.email)}" required><label for="client-status">Demo account label</label><select id="client-status"><option ${c.status==='Active'?'selected':''}>Active</option><option ${c.status==='Review'?'selected':''}>Review</option></select><label for="client-note">Internal manager note</label><textarea id="client-note" maxlength="1500">${escapeHtml(c.note)}</textarea><div class="form-error" id="client-edit-error" role="alert"></div><button class="button primary" type="submit">Save client profile</button></form>`)};
const adminBeforeManagement=renderAdmin;
renderAdmin=function(){ensureClient();adminBeforeManagement();if(['overview','clients'].includes(adminTab)){const first=$('#admin-view .admin-layout>div');first.insertAdjacentHTML('afterbegin',`<section class="panel client-control"><div class="client-control-identity"><span class="avatar">${escapeHtml(demo.client.name.split(/\s+/).map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${escapeHtml(demo.client.name)}</strong><small>${escapeHtml(demo.client.email)} · CL-1001</small></div><span class="pill">${demo.client.status}</span></div><div class="client-control-actions"><button class="button secondary" data-action="edit-client">Edit profile</button><button class="button secondary" data-action="client-plan">Manage investment plan</button><button class="button secondary" data-action="preview-contract">Documents & print</button><button class="button primary" data-action="view-client">View client workspace ${icon('out')}</button></div>${demo.client.note?`<p class="manager-note">Internal note: ${escapeHtml(demo.client.note)}</p>`:''}</section>`)}refreshClientProfile()};
actions['client-plan']=()=>{if($('#modal').open)$('#modal').close();setRole('client');tab='tariffs';renderClientTab();toast('Editing the client demo plan. Changes will appear in both workspaces.')};
document.addEventListener('submit',e=>{if(e.target.id!=='client-edit-form')return;e.preventDefault();const name=$('#client-name').value.trim();if(name.length<2){$('#client-edit-error').textContent='Enter a client name.';return}demo.client={name,email:$('#client-email').value.trim(),status:$('#client-status').value,note:$('#client-note').value.trim()};ensureClient();activity('Manager updated client profile CL-1001');persist();$('#modal').close();renderAdmin();refreshClientProfile();toast('Client workspace updated.')});
const originalContractContent=contractContent;
contractContent=function(){ensureClient();return originalContractContent().replaceAll('John Doe',escapeHtml(demo.client.name))};
const resetBeforeProfile=actions['confirm-reset'];actions['confirm-reset']=()=>{resetBeforeProfile();ensureClient();refreshClientProfile();renderSessionWidget();$('#state-filter').value='';$('#station-search').value='';$('#search-results').hidden=true;$('#clear-search').hidden=true;filter='all';$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));renderMap();actions['fit-map']()};
// Observe the map surface itself, including changes when returning from hidden tabs.
let lastMapSize='',mapResizeTimer;
const mapResizeObserver=new ResizeObserver(entries=>{const rect=entries[0]?.contentRect;if(!rect?.width||!rect.height){lastMapSize='';return}const size=rect.width+':'+rect.height;if(size===lastMapSize)return;lastMapSize=size;clearTimeout(mapResizeTimer);mapResizeTimer=setTimeout(()=>{if(!map)return;map.stop();map.invalidateSize({pan:false,animate:false});const rows=filteredStations();const nationwide=!$('#state-filter').value&&!$('#station-search').value.trim()&&filter==='all';if(nationwide)map.fitBounds([[24.8,-124.7],[49,-66.8]],{paddingTopLeft:[25,110],paddingBottomRight:[25,70],animate:false});else if(rows.length)map.fitBounds(rows.map(s=>[s.lat,s.lng]),{paddingTopLeft:[30,110],paddingBottomRight:[30,70],maxZoom:8,animate:false})},120)});
mapResizeObserver.observe($('#map'));
// Keep current client labels consistent across both workspace views.
const adminBeforeNames=renderAdmin;
renderAdmin=function(){adminBeforeNames();if(demo.client?.name==='John Doe')return;const walker=document.createTreeWalker($('#admin-view'),NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode()))if(node.nodeValue.includes('John Doe')&&!node.parentElement.closest('.activity-row'))node.nodeValue=node.nodeValue.replaceAll('John Doe',demo.client.name)};
